// 50M-document collection on a 3-member replica set.
// Issue the build on the PRIMARY and stop there: since 4.2 the default build is
// replicated -- every data-bearing member builds simultaneously and the primary does
// not report the index ready until a majority have finished.
db.orders.createIndex(
  {status: 1, created_at: -1},
  {name: "idx_status_created"}
);

// Watch the build, and watch per-secondary LAG while it runs.
// rs.printReplicationInfo() would show the oplog window of THIS member, not lag.
db.currentOp({"command.createIndexes": {$exists: true}});
rs.printSecondaryReplicationInfo();

// Confirm it landed.
db.orders.getIndexes();
